"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([["507"],{6173(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/awesome-frames/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"link","href":"/awesome-frames/docs/eip-8141","label":"EIP-8141 primer","docId":"eip-8141","unlisted":false},{"type":"link","href":"/awesome-frames/docs/viem-frame-tx","label":"viem-frame-tx","docId":"viem-frame-tx","unlisted":false},{"type":"category","label":"Recipes","items":[{"type":"link","href":"/awesome-frames/docs/recipes/nostr-frame-account","label":"NostrFrameAccount","docId":"recipes/nostr-frame-account","unlisted":false},{"type":"link","href":"/awesome-frames/docs/recipes/lightning-rsa","label":"LightningRSA","docId":"recipes/lightning-rsa","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/awesome-frames/docs/recipes/"},{"type":"category","label":"The grimoire","items":[{"type":"link","href":"/awesome-frames/docs/grimoire/toy-curve-ecdh","label":"ToyCurveECDH","docId":"grimoire/toy-curve-ecdh","unlisted":false},{"type":"category","label":"YoloRSA","items":[{"type":"link","href":"/awesome-frames/docs/grimoire/yolo-rsa-wide","label":"YoloRSA: wide tiers","docId":"grimoire/yolo-rsa-wide","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/awesome-frames/docs/grimoire/yolo-rsa"}],"collapsed":true,"collapsible":true,"href":"/awesome-frames/docs/grimoire/"}]},"docs":{"eip-8141":{"id":"eip-8141","title":"EIP-8141 primer","description":"EIP-8141 introduces a new transaction type (0x06) built from a list of frames \u2014 contract calls tagged with a mode:","sidebar":"docsSidebar"},"grimoire/index":{"id":"grimoire/index","title":"The grimoire","description":"contracts/src/grimoire/ is a separate, deliberately-insecure track \u2014 not Frame-tx recipes, an excuse to get fluent in raw Yul by implementing classic asymmetric primitives directly, as legibly as the language allows.","sidebar":"docsSidebar"},"grimoire/toy-curve-ecdh":{"id":"grimoire/toy-curve-ecdh","title":"ToyCurveECDH","description":"Elliptic-curve Diffie-Hellman over y\xb2 = x\xb3 + 2x + 2 (mod 17) \u2014 the textbook toy curve from Hankerson/Menezes/Vanstone\'s Guide to Elliptic Curve Cryptography. Its group has prime order 19 \u2014 small enough to enumerate and print on one page, which is the entire point: the same chord-and-tangent geometry that powers this repo\'s real secp256k1/BIP-340 work (BIP340.sol, NostrFrameAccount.yul), shrunk down until a curious reader can verify it by hand, and small enough that recovering a private scalar from its public point is a nineteen-iteration for loop, not a research problem.","sidebar":"docsSidebar"},"grimoire/yolo-rsa":{"id":"grimoire/yolo-rsa","title":"YoloRSA","description":"A ladder of deliberately-weak textbook RSA \\"wallets,\\" each sized to a specific real-world cracking difficulty \u2014 from mental arithmetic up to \\"needs a real factoring tool.\\" The idea: deploy one, fund it with testnet ETH, publish nothing but its public key (baked directly into the contract\'s own bytecode), and see how long a stranger takes to factor the modulus, recover the private exponent, forge a signature, and drain it.","sidebar":"docsSidebar"},"grimoire/yolo-rsa-wide":{"id":"grimoire/yolo-rsa-wide","title":"YoloRSA: wide tiers","description":"The wide-modulus sibling of YoloRSA: moduli spanning two EVM words (up to 512 bits) instead of one, sized against a real GNFS-based cost model rather than \\"small enough for a naive script.\\"","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"Introduction","description":"A playground for crafting EIP-8141 Frame transactions on Ethereum \u2014 Hardhat v3 + rocketh for contracts, plus a standalone viem-based encoder package, wired up against the only public Frame-tx-capable testnet that exists today.","sidebar":"docsSidebar"},"recipes/index":{"id":"recipes/index","title":"Recipes","description":"A Frame account recipe is: a VERIFY-frame target contract, a signature scheme, and a script proving the round trip against a live (or simulated) Frame-tx-capable network.","sidebar":"docsSidebar"},"recipes/lightning-rsa":{"id":"recipes/lightning-rsa","title":"LightningRSA","description":"A self-verifying EIP-8141 account authorized by a real RSASSA-PKCS1-v1_5/SHA-256 signature (RFC 8017 \xa79.2/\xa78.2) \u2014 unlike the grimoire\'s YoloRSA (deliberately tiny, deliberately unpadded), this is meant to be sound at any modulus width an operator actually deploys with. Default target: RSA-2048.","sidebar":"docsSidebar"},"recipes/nostr-frame-account":{"id":"recipes/nostr-frame-account","title":"NostrFrameAccount","description":"A minimal, self-verifying Frame account authorized by a BIP-340/Nostr Schnorr signature instead of ECDSA \u2014 the same secp256k1 keypair that signs a Nostr event can authorize a Frame transaction directly, no key derivation in between.","sidebar":"docsSidebar"},"viem-frame-tx":{"id":"viem-frame-tx","title":"viem-frame-tx","description":"npm","sidebar":"docsSidebar"}}}}')}}]);